python - <<'PY'
import warnings
from marshmallow import Schema, fields, missing, ValidationError
from marshmallow.warnings import RemovedInMarshmallow4Warning
from marshmallow_jsonschema import JSONSchema
warnings.simplefilter('error', RemovedInMarshmallow4Warning)
for cls in (fields.Field, fields.Raw):
    f = cls(load_default=lambda: {'a': 1}, dump_default=lambda: {'b': 2})
    assert f.deserialize(missing) == {'a': 1}
    assert f.serialize('value', {}) == {'b': 2}
    assert f.metadata == {}
    assert f.deserialize('unchanged') == 'unchanged'
    assert cls(load_default=None).deserialize(None) is None
    assert not cls(load_default=None, allow_none=False).allow_none
    assert cls().deserialize(missing) is missing
    assert cls().serialize('absent', {}) is missing
    try:
        cls(required=True, load_default=0)
    except ValueError as exc:
        assert 'load_default' in str(exc)
    else:
        raise AssertionError('required load_default accepted')
f = fields.Constant('fixed', load_default='ignored', dump_default='ignored')
assert f.deserialize(missing) == f.deserialize('input') == f.serialize('absent', {}) == 'fixed'
class Child(Schema):
    value = fields.Int()
class Parent(Schema):
    raw = fields.Raw(load_default='loaded', dump_default='dumped')
    child = fields.Nested(Child, load_default=lambda: {'value': 1}, dump_default={'value': 2})
    omitted = fields.Str(dump_default=lambda: 'not in json schema')
p = Parent()
assert p.load({}) == {'raw': 'loaded', 'child': {'value': 1}}
assert p.dump({}) == {'raw': 'dumped', 'child': {'value': 2}, 'omitted': 'not in json schema'}
properties = JSONSchema().dump(p)['definitions']['Parent']['properties']
assert properties['raw']['default'] == 'dumped'
assert properties['child']['default'] == {'value': 2}
assert 'default' not in properties['omitted']
print('New API checks passed with field deprecation warnings treated as errors.')
PY
